use crate::aap::caps::http_client;

/// The hosts named in this node's `with HTTPClient<[...]>` clause. The host
/// enforces the same set at the crossing, where a request outside it traps.
/// This node checks each URL against the set before asking, so one stray
/// subscription becomes a recorded failure instead of failing the whole tick.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the lowercase host from an absolute http(s) URL.
/// Returns an error string if the URL is not one this node will fetch.
fn host_of(url: &str) -> Result<String, String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if let Some(r) = lower.strip_prefix("https://") {
        r
    } else if let Some(r) = lower.strip_prefix("http://") {
        r
    } else {
        return Err(String::from("unsupported or missing URL scheme"));
    };

    // The authority ends at the first '/', '?' or '#'.
    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Drop any userinfo.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // Drop any port. IPv6 literals are never on the allowlist, so reject them.
    if host_port.starts_with('[') {
        return Err(String::from("host not permitted"));
    }
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    let host = host.trim_end_matches('.');

    if host.is_empty() {
        return Err(String::from("URL has no host"));
    }
    Ok(String::from(host))
}

fn allowed(host: &str) -> bool {
    ALLOWED_HOSTS.iter().any(|h| *h == host)
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();
        let mut seen: Vec<String> = Vec::new();

        for url in subscriptions.urls {
            let url_trimmed = String::from(url.trim());

            if seen.iter().any(|s| *s == url_trimmed) {
                continue;
            }
            seen.push(url_trimmed.clone());

            let host = match host_of(&url_trimmed) {
                Ok(h) => h,
                Err(e) => {
                    failures.push(FetchFailure {
                        url: url_trimmed,
                        error: e,
                    });
                    continue;
                }
            };

            if !allowed(&host) {
                failures.push(FetchFailure {
                    url: url_trimmed,
                    error: String::from("host not in this node's HTTP allowlist"),
                });
                continue;
            }

            match http_client::fetch(&url_trimmed) {
                Ok(body) => documents.push(FeedDocument {
                    url: url_trimmed,
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: url_trimmed,
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
